package app.books.reader;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class WidgetConfigureActivity extends Activity {
 @Override public void onCreate(Bundle state){super.onCreate(state);int id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);setResult(RESULT_CANCELED);if(id==AppWidgetManager.INVALID_APPWIDGET_ID){finish();return;}AppWidgetProviderInfo provider=AppWidgetManager.getInstance(this).getAppWidgetInfo(id);if(provider==null||!provider.provider.equals(new ComponentName(this,BooksWidget.class))){finish();return;}
  LinkedHashMap<String,String> groups=new LinkedHashMap<>();groups.put("Recently opened","recent");groups.put("Favorites","favorites");groups.put("All books","all");JSONArray books=BooksWidget.books(this);for(int i=0;i<books.length();i++)try{JSONArray tags=books.getJSONObject(i).optJSONArray("tags");if(tags!=null)for(int j=0;j<tags.length();j++)groups.put(tags.getString(j),"tag:"+tags.getString(j));}catch(Exception ignored){}
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);int space=(int)(20*getResources().getDisplayMetrics().density);root.setPadding(space,space,space,space);TextView title=new TextView(this);title.setText("Your reading widget");title.setTextSize(24);root.addView(title);RadioGroup radio=new RadioGroup(this);String selected=getSharedPreferences("books",0).getString("widget-group-"+id,"recent");HashMap<Integer,String> values=new HashMap<>();for(Map.Entry<String,String> group:groups.entrySet()){RadioButton choice=new RadioButton(this);choice.setText(group.getKey());choice.setId(View.generateViewId());choice.setMinHeight((int)(52*getResources().getDisplayMetrics().density));values.put(choice.getId(),group.getValue());radio.addView(choice);if(selected.equals(group.getValue()))radio.check(choice.getId());}root.addView(radio);Button save=new Button(this);save.setText("Save");save.setOnClickListener(view->{String chosen=values.get(radio.getCheckedRadioButtonId());if(chosen==null)chosen="recent";getSharedPreferences("books",0).edit().putString("widget-group-"+id,chosen).apply();new BooksWidget().onUpdate(this,AppWidgetManager.getInstance(this),new int[]{id});setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));finish();});root.addView(save);ScrollView scroll=new ScrollView(this);scroll.addView(root);scroll.setBackgroundColor(android.graphics.Color.rgb(248,247,243));scroll.setOnApplyWindowInsetsListener((view,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);return WindowInsets.CONSUMED;}view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});setContentView(scroll);if(Build.VERSION.SDK_INT>=30){int flags=WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS;getWindow().getInsetsController().setSystemBarsAppearance(flags,flags);}
 }
}
